{
  "decision-size-ferry-departure-topup": "WITH voyage AS (SELECT SUM(net_change) OVER (ORDER BY step_no ROWS UNBOUNDED PRECEDING) AS offset_kwh FROM voyage_step), bounds AS (SELECT MIN(offset_kwh) AS low_kwh, MAX(offset_kwh) AS high_kwh FROM (SELECT 0 AS offset_kwh UNION ALL SELECT offset_kwh FROM voyage)), options AS (SELECT c.source_id, p.package_code, p.fee_cents, p.buy_kwh, c.initial_kwh + p.buy_kwh AS departure_kwh, c.reserve_kwh, c.capacity_kwh FROM sailing_card AS c CROSS JOIN dock_package AS p) SELECT source_id, package_code, fee_cents, departure_kwh + (SELECT COALESCE(SUM(net_change), 0) FROM voyage_step) AS arrival_kwh FROM options CROSS JOIN bounds WHERE departure_kwh + low_kwh >= reserve_kwh AND departure_kwh + high_kwh <= capacity_kwh ORDER BY fee_cents, buy_kwh, package_code LIMIT 1",
  "decision-size-opening-pick-face-reserve": "WITH deficits AS (SELECT d.timetable_id, w.wave_no, SUM(w.pick_qty - d.drop_qty) OVER (PARTITION BY d.timetable_id ORDER BY w.wave_no ROWS UNBOUNDED PRECEDING) + d.drop_qty AS deficit FROM pick_wave AS w JOIN tug_drop AS d ON d.wave_no = w.wave_no), ranked AS (SELECT timetable_id, wave_no, deficit, ROW_NUMBER() OVER (PARTITION BY timetable_id ORDER BY deficit DESC, wave_no) AS wave_rank FROM deficits) SELECT r.timetable_id, MAX(0, r.deficit) AS opening_cartons, r.wave_no AS tight_wave, s.note_id AS timetable_note FROM ranked AS r JOIN signed_timetable AS s ON s.timetable_id = r.timetable_id WHERE r.wave_rank = 1 ORDER BY opening_cartons, r.timetable_id LIMIT 1",
  "decision-sky-scaled-aperture-excess": "WITH measured AS (SELECT t.visit_id, t.gross_ct * s.pixel_n - s.gross_ct * t.pixel_n AS numerator, s.pixel_n AS denominator, t.source_id AS target_source, s.source_id AS sky_source FROM aperture_notes AS t JOIN aperture_notes AS s ON s.visit_id = t.visit_id WHERE t.patch_kind = 'target' AND s.patch_kind = 'sky') SELECT visit_id, (10 * numerator + denominator / 2) / denominator AS net_tenths, target_source, sky_source FROM measured WHERE numerator >= 20 * denominator ORDER BY visit_id",
  "decision-sliding-phase-retention": "WITH retained AS (SELECT invoice_day, gross_cents, CASE phase WHEN 'frame' THEN gross_cents / 10 WHEN 'finish' THEN gross_cents / 5 END AS held FROM invoice), events AS (SELECT invoice_day AS settlement_day, gross_cents, held AS withheld_cents, 0 AS released_cents FROM retained UNION ALL SELECT invoice_day + 2, 0, 0, held FROM retained) SELECT settlement_day, SUM(gross_cents) AS gross_cents, SUM(withheld_cents) AS withheld_cents, SUM(released_cents) AS released_cents, SUM(gross_cents - withheld_cents + released_cents) AS payable_cents FROM events GROUP BY settlement_day ORDER BY settlement_day"
}
